'use client';
import { useState, useEffect } from "react";

export function TextReveal({ word, textColor, brandYellow }) {
  const [reset, setReset] = useState(0);
  const WORD = word || "Suvidha";
  
  // Custom logic to handle the branding (Su is yellow, vidha is green)
  // If no branding logic needed, just uses textColor
  
  return (
    <div style={{ display: 'inline-block' }}>
      <div key={reset}>
        <h1 className="reveal-h1" style={{ margin: 0, padding: 0, cursor: 'pointer' }} onClick={() => setReset(reset + 1)}>
          {WORD.split("").map((char, i) => {
            let charColor = textColor || 'var(--brand)';
            if (WORD === "Suvidha" && i < 2) {
              charColor = brandYellow || 'var(--brand-yellow)';
            }
            
            return (
              <span 
                style={{ 
                   "--index": i,
                   color: charColor,
                   display: 'inline-block',
                   opacity: 0,
                   animation: 'reveal 0.5s ease-in-out forwards',
                   animationDelay: `calc(0.05s * ${i})`
                }}
                key={i}>
                {char === " " ? "\u00A0" : char}
              </span>
            );
          })}
        </h1>
      </div>
      <style jsx="true">{`
        .reveal-h1 {
          font-size: 1.8rem;
          font-weight: 800;
          letter-spacing: -0.02em;
          overflow: hidden;
          line-height: 1;
          display: flex;
        }

        @keyframes reveal {
          0% {
            transform: translateY(100%);
            opacity: 0;
          }
          100% {
            transform: translateY(0%);
            opacity: 1;
          }
        }
      `}</style>
    </div>
  );
}
